const items = $input.all();
// Combine sentiment + technicals into weighted score
items.forEach(item => {
  const sentiment = item.json.sentiment_score || 0;
  const momentum = item.json.momentum_score || 0;
  const rsi = item.json.rsi || 50;
  const volumeRatio = item.json.volume_ratio || 1;
  const ret5d = item.json.return_5d || 0;

  // Multi-factor scoring
  const rsiComponent = (rsi - 50) / 50;
  const retComponent = Math.max(-1, Math.min(1, ret5d * 10));
  const volComponent = Math.max(-1, Math.min(1, (volumeRatio - 1) * 2));
  const sentComponent = sentiment * 0.25;

  // Enhanced prediction score with all factors
  item.json.prediction_score = rsiComponent * 0.20 + retComponent * 0.30 + volComponent * 0.15 + sentComponent * 0.35;
  item.json.predicted_return = item.json.prediction_score * 2.0;
});
// Sort by prediction_score descending, take top 10
items.sort((a, b) => b.json.prediction_score - a.json.prediction_score);
return items.slice(0, 10).map((item, i) => ({
  json: {
    rank: i + 1,
    ticker: item.json.ticker,
    predicted_return: Math.round(item.json.predicted_return * 10000) / 10000,
    confidence: Math.round(item.json.prediction_score * 10000) / 10000,
    sentiment: item.json.sentiment_score,
    momentum: item.json.momentum_score,
    rsi: item.json.rsi,
    volume_ratio: item.json.volume_ratio,
    return_5d: item.json.return_5d,
    price: item.json.price,
    timestamp: new Date().toISOString()
  }
}));

